const http = require('http');
const axios = require('/testbed');
const s = http.createServer(function (q, r) { q.resume(); q.on('end', function () { r.end('ok'); }); }).listen(4455, async function () {
  try { await axios.post('http://localhost:4455/', 'x'.repeat(2e7)); console.log('default ok'); } catch (e) { console.log(e.message); }
  try { await axios.post('http://localhost:4455/', 'x'.repeat(2e7), { maxBodyLength: -1 }); console.log('-1 ok'); } catch (e) { console.log(e.message); }
  try { await axios.post('http://localhost:4455/', 'x'.repeat(2e7), { maxBodyLength: 1000 }); console.log('limit not enforced!'); } catch (e) { console.log('1000:', e.message); }
  s.close();
});

